t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
F={
 't^k exp(-m/t)':lambda p: t**p[0]*np.exp(-p[1]/t),
 't^k exp(-m t)':lambda p: t**p[0]*np.exp(-p[1]*t),
 't^k exp(m t)':lambda p: t**p[0]*np.exp(p[1]*t),
 't^k*log(1+m t)':lambda p: t**p[0]*np.log(1+p[1]*t),
 't^k/(1+m t)':lambda p: t**p[0]/(1+p[1]*t),
 'log(t)*t^k':lambda p: np.log(t)*t**p[0],
 'sin(m t)*t^k':lambda p: np.sin(p[1]*t)*t**p[0],
}
G={
 'A^k exp(-m A)':lambda p: A**p[0]*np.exp(-p[1]*A),
 'A^k/(1+mA)':lambda p: A**p[0]/(1+p[1]*A),
 'A^k*log(1+mA)':lambda p: A**p[0]*np.log(1+p[1]*A),
 'A^k*tanh(mA)':lambda p: A**p[0]*np.tanh(p[1]*A),
 'A^k*cos(mA)':lambda p: A**p[0]*np.cos(p[1]*A),
 'A^k*exp(-m/A)':lambda p: A**p[0]*np.exp(-p[1]/A),
 'exp(-k A^m)':lambda p: np.exp(-p[0]*A**p[1]),
}
rng=np.random.default_rng(2)
out=[]
for fn,f in F.items():
  for gn,g in G.items():
    best=None
    for trial in range(5):
        def resid(p):
            X=np.column_stack([1/t, A/(1+p[0]*A)*t**3, np.sin(p[1]*np.sqrt(A))*t**1.5, f(p[2:4])*g(p[4:6])])
            b=np.linalg.lstsq(X,y,rcond=None)[0]
            return y-X@b
        p0=np.concatenate([[rng.uniform(-0.3,0.5),rng.uniform(1.8,2.3)],rng.uniform(-1,1,4)])
        try:
            r=least_squares(resid,p0,max_nfev=150)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    if best is not None and np.isfinite(best.cost): out.append((round(best.cost*2/len(y)/np.var(y),6), fn, gn, np.round(best.x,4)))
out.sort(key=lambda z:z[0])
for o in out[:6]: print(o)
